/*
 * Execute unchanged current driver validator bodies generated by the runner.
 * Explicit seams: clock/sleep, logs, link metric and request policy/transport.
 * Successful request seam uses the production owned work and REAL sync setter. WCID
 * fields and secure-RX timestamp are synthetic inputs, never hardware evidence.
 * This does NOT execute mt7925_ops, the secure request gate or MCU transport.
 */
#include "mlo_pair_transition.h"
#include "mlo_secure_shrink.h"
#include "mlo_steer_validate.h"

enum mt7925_mlo_link_metric_state {
	MT7925_MLO_METRIC_INVALID, MT7925_MLO_METRIC_LIVE,
	MT7925_MLO_METRIC_CACHED, MT7925_MLO_METRIC_UNKNOWN,
};

struct mlo_validator_context {
	struct mlo_fixture *f;
	unsigned long clock;
	int request_result;
	unsigned int request_count;
	u16 requested;
	bool stop_at_settle, wait_rollback_grow, inject_survivor_rx;
	bool switch_confirmed, rollback_confirmed, rollback_timeout, rollback_refused;
	bool grow_pending_at_confirmation;
	bool teardown_wait, invalidated, rollback_failed;
	struct completion sleep_entered, worker_done;
};

static struct mlo_validator_context *mlo_vctx;
/* namespace external prototype declarations; no production symbol linked */
#define mt7925_mlo_steer_request mlo_test_request

static void mlo_validator_log(const char *fmt, ...)
{
	char text[512];
	va_list args;

	va_start(args, fmt);
	vscnprintf(text, sizeof(text), fmt, args);
	va_end(args);
	if (strstr(text, "MLO_STEER_CORE_COMPLETED:"))
		mlo_vctx->switch_confirmed = true;
	if (strstr(text, "MLO_STEER_ROLLBACK_CONFIRMED:")) {
		mlo_vctx->rollback_confirmed = true;
		mlo_vctx->grow_pending_at_confirmation =
			!completion_done(&mlo_vctx->f->outer_done);
	}
	if (strstr(text, "MLO_STEER_ROLLBACK_TIMEOUT:"))
		mlo_vctx->rollback_timeout = true;
	if (strstr(text, "MLO_STEER_ROLLBACK_REFUSED:"))
		mlo_vctx->rollback_refused = true;
	if (strstr(text, "MLO_STEER_INVALIDATED:"))
		mlo_vctx->invalidated = true;
	if (strstr(text, "MLO_STEER_ROLLBACK_FAILED:"))
		mlo_vctx->rollback_failed = true;
	pr_info("mlo_validator_test: %s", text);
}

static void mlo_validator_sleep(unsigned int milliseconds)
{
	if (mlo_vctx->teardown_wait) {
		struct mt792x_vif *mvif = (void *)mlo_vctx->f->sdata->vif.drv_priv;
		unsigned long deadline = jiffies + 2 * HZ;

		complete(&mlo_vctx->sleep_entered);
		/* Teardown closes this gate before it joins the ordinary work.
		 * Never wait on wiphy or on the core worker that requires it.
		 */
		while (READ_ONCE(mvif->mlo_completion.enabled) &&
		       time_before(jiffies, deadline))
			msleep(1);
	}
	mlo_vctx->clock += msecs_to_jiffies(milliseconds);
	if (mlo_vctx->stop_at_settle && milliseconds == 1000)
		mlo_vctx->f->sdata->vif.cfg.assoc = false;
}

static enum mt7925_mlo_link_metric_state
mt7925_mlo_link_metric(struct mt792x_vif *mvif, u16 active, unsigned int link,
			 s32 *score)
{
	*score = 0;
	return MT7925_MLO_METRIC_UNKNOWN; /* explicit metric-policy double */
}

static const char *mt7925_mlo_metric_state_str(enum mt7925_mlo_link_metric_state s)
{
	return "TEST_UNKNOWN";
}

static int mt7925_mlo_steer_request(struct mt792x_dev *dev,
				struct ieee80211_vif *vif, u16 target,
				const struct mt792x_mlo_ticket *predecessor,
				struct mt792x_mlo_ticket *ticket)
{
	struct mlo_fixture *f = mlo_vctx->f;

	mlo_vctx->request_count++;
	mlo_vctx->requested = target;
	if (mlo_vctx->request_result)
		return mlo_vctx->request_result;
	if (mt7925_mlo_completion_request_after(vif, target, predecessor, ticket))
		return -EINVAL;
	if (mlo_vctx->wait_rollback_grow &&
	    !wait_for_completion_timeout(&f->grow_entered, 2 * HZ))
		return -ETIMEDOUT;
	if (mlo_vctx->inject_survivor_rx) {
		/* Deterministic declared evidence on survivor, not incoming link. */
		f->peer[2]->mlo_valid_rx_packets++;
		WRITE_ONCE(f->peer[2]->mlo_valid_rx_jiffies, mlo_vctx->clock + 1);
	}
	return 0;
}

/* Narrow, reversible compile-time seams around UNCHANGED function bodies. */
#pragma push_macro("jiffies")
#pragma push_macro("msleep")
#pragma push_macro("dev_info")
#pragma push_macro("dev_warn")
#undef jiffies
#define jiffies (mlo_vctx->clock)
#define msleep mlo_validator_sleep
#undef dev_info
#undef dev_warn
#define dev_info(device, ...) mlo_validator_log(__VA_ARGS__)
#define dev_warn(device, ...) mlo_validator_log(__VA_ARGS__)
#include "mlo_validator_body.inc"
#pragma pop_macro("dev_warn")
#pragma pop_macro("dev_info")
#pragma pop_macro("msleep")
#pragma pop_macro("jiffies")
#undef mt7925_mlo_steer_request

static void mlo_driver_confirms_forward_before_outer_return(struct kunit *test)
{
	struct mlo_fixture *f = test->priv;
	struct mlo_validator_context ctx = {
		.f = f, .clock = jiffies + 100, .stop_at_settle = true,
	};
	bool entered;
	struct mt792x_vif *mvif = (void *)f->sdata->vif.drv_priv;
	struct mt792x_mlo_result result;

	KUNIT_ASSERT_EQ(test, mlo_seed_active(f, 6), 0);
	f->block_new = 5;
	KUNIT_ASSERT_EQ(test, mt7925_mlo_completion_request(&f->sdata->vif,
					5, &mvif->mlo_steer_ticket), 0);
	entered = wait_for_completion_timeout(&f->grow_entered, 2 * HZ);
	KUNIT_EXPECT_TRUE(test, entered);
	if (entered) {
		mlo_vctx = &ctx;
		mt7925_mlo_steer_switch_validate(f->dev, &f->sdata->vif,
			mvif, 6, 5, &mvif->mlo_steer_ticket);
		KUNIT_EXPECT_FALSE(test, completion_done(&f->outer_done));
		KUNIT_EXPECT_FALSE(test, ctx.switch_confirmed);
		KUNIT_EXPECT_EQ(test, ctx.request_count, 0U); /* no overlapping rollback */
		f->sdata->vif.cfg.assoc = true;
	}
	complete_all(&f->grow_release);
	KUNIT_EXPECT_EQ(test, mlo_completion_flush_result(f,
					 &mvif->mlo_steer_ticket, &result), 0);
	mlo_vctx = NULL;
}

static void mlo_driver_refused_rollback_has_no_completion(struct kunit *test)
{
	struct mlo_fixture *f = test->priv;
	struct mlo_validator_context ctx = {
		.f = f, .clock = jiffies + 100, .request_result = -EBUSY,
	};
	struct mt792x_vif *mvif = (void *)f->sdata->vif.drv_priv;
	struct mt792x_mlo_result result;

	KUNIT_ASSERT_EQ(test, mlo_seed_active(f, 5), 0);
	f->peer[0]->wcid.hw_key_idx = 255; /* no forward readiness */
	KUNIT_ASSERT_EQ(test, mt7925_mlo_completion_request(&f->sdata->vif,
					5, &mvif->mlo_steer_ticket), 0);
	KUNIT_ASSERT_EQ(test, mlo_completion_flush_result(f,
					 &mvif->mlo_steer_ticket, &result), 0);
	mlo_vctx = &ctx;
	mt7925_mlo_steer_switch_validate(f->dev, &f->sdata->vif,
		mvif, 6, 5, &mvif->mlo_steer_ticket);
	KUNIT_EXPECT_EQ(test, ctx.request_count, 1U);
	KUNIT_EXPECT_EQ(test, ctx.requested, (u16)6);
	KUNIT_EXPECT_TRUE(test, ctx.rollback_refused);
	KUNIT_EXPECT_FALSE(test, ctx.rollback_confirmed);
	KUNIT_EXPECT_EQ(test, f->sdata->vif.active_links, (u16)5);
	KUNIT_EXPECT_FALSE(test, completion_done(&f->outer_done));
	mlo_vctx = NULL;
}

static void mlo_driver_confirms_rollback_while_grow_will_fail(struct kunit *test)
{
	struct mlo_fixture *f = test->priv;
	struct mlo_validator_context ctx = {
		.f = f, .clock = jiffies + 100, .wait_rollback_grow = true,
		.inject_survivor_rx = true,
	};
	struct mt792x_vif *mvif = (void *)f->sdata->vif.drv_priv;
	struct mt792x_mlo_result result;
	bool entered;

	KUNIT_ASSERT_EQ(test, mlo_seed_active(f, 5), 0);
	f->block_new = 6;
	f->fail_new = 6;
	KUNIT_ASSERT_EQ(test, mt7925_mlo_completion_request(&f->sdata->vif,
					6, &mvif->mlo_steer_ticket), 0);
	entered = wait_for_completion_timeout(&f->grow_entered, 2 * HZ);
	KUNIT_EXPECT_TRUE(test, entered);
	if (!entered)
		goto release;
	mvif->mlo_steer_validating = true;
	mvif->mlo_steer_rollback_pending = true;
	f->peer[2]->mlo_valid_rx_packets++;
	WRITE_ONCE(f->peer[2]->mlo_valid_rx_jiffies, ctx.clock + 1);
	mlo_vctx = &ctx;
	mt7925_mlo_steer_switch_validate(f->dev, &f->sdata->vif,
		mvif, 6, 3, &mvif->mlo_steer_ticket);
	KUNIT_EXPECT_EQ(test, ctx.request_count, 0U);
	KUNIT_EXPECT_FALSE(test, completion_done(&f->outer_done));
	KUNIT_EXPECT_FALSE(test, ctx.rollback_confirmed); /* required contract */
release:
	complete_all(&f->grow_release);
	KUNIT_EXPECT_EQ(test, mlo_completion_flush_result(f,
					 &mvif->mlo_steer_ticket, &result), -EIO);
	KUNIT_EXPECT_EQ(test, f->sdata->vif.active_links, (u16)4);
	mlo_vctx = NULL;
}

static void mlo_driver_rejects_precompletion_rx_and_old_ticket(struct kunit *test)
{
	struct mlo_fixture *f = test->priv;
	struct mt792x_mlo_ticket ticket, fresh;
	struct mt792x_mlo_result result;
	u16 secure;
	int i;

	KUNIT_ASSERT_EQ(test, mlo_seed_active(f, 6), 0);
	KUNIT_ASSERT_EQ(test, mt7925_mlo_completion_request(&f->sdata->vif,
							5, &ticket), 0);
	KUNIT_ASSERT_EQ(test, mlo_completion_flush_result(f, &ticket, &result), 0);
	mlo_vctx = &(struct mlo_validator_context) { .f = f,
		.clock = result.finished_jiffies + 10 };
	for (i = 0; i < 3; i++) {
		f->peer[i]->mlo_valid_rx_packets = 1;
		f->peer[i]->mlo_valid_rx_jiffies = result.finished_jiffies - 1;
	}
	/* Exact production reader: old incoming RX cannot authenticate a commit. */
	secure = mt7925_mlo_secure_links(&f->sdata->vif, 5, result.finished_jiffies, true);
	KUNIT_EXPECT_EQ(test, secure, (u16)0);
	f->peer[2]->mlo_valid_rx_jiffies = result.finished_jiffies + 1;
	secure = mt7925_mlo_secure_links(&f->sdata->vif, 5, result.finished_jiffies, true);
	KUNIT_EXPECT_EQ(test, secure, (u16)4);
	KUNIT_EXPECT_FALSE(test, mt7925_mlo_completion_validate(&f->sdata->vif,
							      &ticket, secure));
	f->peer[0]->mlo_valid_rx_jiffies = result.finished_jiffies + 1;
	secure = mt7925_mlo_secure_links(&f->sdata->vif, 5, result.finished_jiffies, true);
	KUNIT_EXPECT_EQ(test, secure, (u16)5);
	KUNIT_EXPECT_TRUE(test, mt7925_mlo_completion_validate(&f->sdata->vif,
							     &ticket, secure));
	KUNIT_ASSERT_EQ(test, mt7925_mlo_completion_request(&f->sdata->vif,
							5, &fresh), 0);
	KUNIT_EXPECT_FALSE(test, mt7925_mlo_completion_validate(&f->sdata->vif,
							      &ticket, secure));
	KUNIT_EXPECT_EQ(test, mlo_completion_flush_result(f, &fresh, &result), 0);
	mlo_vctx = NULL;
}

static void mlo_validator_ordinary_work(struct work_struct *work)
{
	struct mlo_validator_context *ctx = mlo_vctx;
	struct mt792x_vif *mvif = (void *)ctx->f->sdata->vif.drv_priv;

	mt7925_mlo_steer_switch_validate(ctx->f->dev, &ctx->f->sdata->vif,
		mvif, 6, 5, &mvif->mlo_steer_ticket);
	complete(&ctx->worker_done);
}

static void mlo_driver_teardown_joins_validator_under_wiphy(struct kunit *test)
{
	struct mlo_fixture *f = test->priv;
	struct mt792x_vif *mvif = (void *)f->sdata->vif.drv_priv;
	struct mlo_validator_context ctx = { .f = f, .clock = jiffies + 100,
		.teardown_wait = true };
	struct mt792x_mlo_result result;
	bool entered, queued;
	int accepted, canceled;

	KUNIT_ASSERT_EQ(test, mlo_seed_active(f, 6), 0);
	init_completion(&ctx.sleep_entered);
	init_completion(&ctx.worker_done);
	INIT_DELAYED_WORK(&mvif->mlo_steer_work, mlo_validator_ordinary_work);
	mlo_vctx = &ctx;
	/* Prevent core progress with the actual lock held by the canceller. */
	wiphy_lock(f->hw->wiphy);
	accepted = mt7925_mlo_completion_request(&f->sdata->vif, 5,
						 &mvif->mlo_steer_ticket);
	queued = queue_delayed_work(system_wq, &mvif->mlo_steer_work, 0);
	entered = wait_for_completion_timeout(&ctx.sleep_entered, HZ);
	mt7925_mlo_completion_stop(&f->sdata->vif);
	canceled = mt7925_mlo_completion_result(&f->sdata->vif,
					      &mvif->mlo_steer_ticket, &result);
	wiphy_work_flush(f->hw->wiphy, NULL);
	wiphy_unlock(f->hw->wiphy);
	KUNIT_EXPECT_EQ(test, accepted, 0);
	KUNIT_EXPECT_TRUE(test, queued);
	KUNIT_EXPECT_TRUE(test, entered);
	KUNIT_EXPECT_TRUE(test, completion_done(&ctx.worker_done));
	KUNIT_EXPECT_TRUE(test, ctx.invalidated);
	KUNIT_EXPECT_EQ(test, canceled, -ECANCELED);
	KUNIT_EXPECT_EQ(test, f->n_events, 0U);
	mlo_vctx = NULL;
}

static void mlo_driver_completed_errno_routes_to_tracked_rollback(struct kunit *test)
{
	struct mlo_fixture *f = test->priv;
	struct mt792x_vif *mvif = (void *)f->sdata->vif.drv_priv;
	struct mlo_validator_context ctx = { .f = f, .clock = jiffies + 100,
		.wait_rollback_grow = true };
	struct mt792x_mlo_result result;

	KUNIT_ASSERT_EQ(test, mlo_seed_active(f, 6), 0);
	f->fail_new = 5;
	f->fail_errno = -EINPROGRESS;
	KUNIT_ASSERT_EQ(test, mt7925_mlo_completion_request(&f->sdata->vif,
					5, &mvif->mlo_steer_ticket), 0);
	KUNIT_ASSERT_EQ(test, mlo_completion_flush_result(f,
					 &mvif->mlo_steer_ticket, &result), -EINPROGRESS);
	KUNIT_ASSERT_EQ(test, result.phase, MT792X_MLO_CORE_DONE);
	reinit_completion(&f->grow_entered);
	reinit_completion(&f->grow_release);
	f->block_new = f->fail_new = 6;
	f->fail_errno = -EIO;
	mvif->mlo_steer_validating = true;
	mlo_vctx = &ctx;
	mt7925_mlo_steer_switch_validate(f->dev, &f->sdata->vif,
		mvif, 6, 5, &mvif->mlo_steer_ticket);
	KUNIT_EXPECT_EQ(test, ctx.request_count, 1U);
	KUNIT_EXPECT_EQ(test, ctx.requested, (u16)6);
	KUNIT_EXPECT_TRUE(test, mvif->mlo_steer_rollback_pending);
	KUNIT_EXPECT_FALSE(test, ctx.rollback_confirmed);
	KUNIT_EXPECT_EQ(test, mlo_completion_flush_result(f,
					 &mvif->mlo_steer_ticket, &result), -EIO);
	mt7925_mlo_steer_switch_validate(f->dev, &f->sdata->vif,
		mvif, 6, 5, &mvif->mlo_steer_ticket);
	KUNIT_EXPECT_TRUE(test, ctx.rollback_failed);
	KUNIT_EXPECT_FALSE(test, ctx.rollback_confirmed);
	KUNIT_EXPECT_FALSE(test, mvif->mlo_steer_validating);
	mlo_vctx = NULL;
}

static struct kunit_case mlo_validator_cases[] = {
	KUNIT_CASE(mlo_driver_confirms_forward_before_outer_return),
	KUNIT_CASE(mlo_driver_refused_rollback_has_no_completion),
	KUNIT_CASE(mlo_driver_confirms_rollback_while_grow_will_fail),
	KUNIT_CASE(mlo_driver_rejects_precompletion_rx_and_old_ticket),
	KUNIT_CASE(mlo_driver_teardown_joins_validator_under_wiphy),
	KUNIT_CASE(mlo_driver_completed_errno_routes_to_tracked_rollback),
	{}
};

static struct kunit_suite mlo_validator_suite = {
	.name = "mlo_activation_validator",
	.init = mlo_fixture_init, .exit = mlo_fixture_exit,
	.test_cases = mlo_validator_cases,
};
kunit_test_suite(mlo_validator_suite);
